from pypdf import PdfReader

reader = PdfReader("/root/sc100-blank.pdf")

# Get detailed checkbox info
fields = reader.get_fields()
for name, field in fields.items():
    if field.get('/FT') == '/Btn':
        # Get the widget annotations for appearance states
        kids = field.get('/Kids', [])
        ap_states = []
        if kids:
            for kid in kids:
                kid_obj = kid.get_object() if hasattr(kid, 'get_object') else kid
                ap = kid_obj.get('/AP', {})
                if ap:
                    n = ap.get('/N', {})
                    if hasattr(n, 'keys'):
                        ap_states.extend(list(n.keys()))
        else:
            ap = field.get('/AP', {})
            if ap:
                n = ap.get('/N', {})
                if hasattr(n, 'keys'):
                    ap_states.extend(list(n.keys()))
        print(f"Checkbox: {name!r}, Value: {field.get('/V', 'N/A')}, AP states: {ap_states}")
PYEOF
